// Circuit Database - 25 real-world circuits with corners
export interface CornerData {
  id: string; name: string; type: string; radius: number;
  entrySpeed: number; apexSpeed: number; exitSpeed: number;
  brakingDistance: number; accelerationDistance: number;
  lateralG: number; longitudinalG: number; camber: number;
  banking: number; elevationChange: number; surfaceGrip: number;
  drsZone: boolean; overtakingDifficulty: number; tyreStress: number;
  brakeEnergy: number; downforceRequirement: number;
  difficultyRating: number; keyOvertakingPoint: boolean;
}

export interface CircuitData {
  id: string; name: string; country: string; region: string;
  length: number; laps: number; altitude: number; direction: string;
  streetCircuit: boolean; numberOfCorners: number;
  overtakingRating: number; tyreDegFactor: number; safetyCarProb: number;
  avgLapTime: number; enginePowerNeed: number; downforceLevel: number;
  brakingDifficulty: number; tractionDemand: number;
  lapRecord: { time: string; driver: string; year: number };
  allCorners: CornerData[];
  weatherPatterns: { rainProb: number; avgTemp: number; windDir: string; windSpeed: number };
  lapTimeReference: { pole: number; fastest: number; midfield: number; slowest: number };
}

