export function getCircuitById(id: string): CircuitData | undefined {
  return WORLD_CIRCUITS_COMPLETE.find(c => c.id === id);
}
export function getCircuitsByRegion(region: string): CircuitData[] {
  return WORLD_CIRCUITS_COMPLETE.filter(c => c.region === region);
}
